## Simple Neural Network in Pure JavaScript

```javascript
class SimpleNeuralNetwork {
  constructor(inputSize, hiddenSize, outputSize, learningRate = 0.1) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;
    this.outputSize = outputSize;
    this.learningRate = learningRate;

    // Initialize weights randomly
    this.weightsInputHidden = Array.from({ length: hiddenSize }, () =>
      Array.from({ length: inputSize }, () => Math.random() * 2 - 1)
    );

    this.weightsHiddenOutput = Array.from({ length: outputSize }, () =>
      Array.from({ length: hiddenSize }, () => Math.random() * 2 - 1)
    );

    // Initialize biases randomly
    this.biasHidden = Array.from({ length: hiddenSize }, () => Math.random() * 2 - 1);
    this.biasOutput = Array.from({ length: outputSize }, () => Math.random() * 2 - 1);
  }

  // Sigmoid activation function
  sigmoid(x) {
    return 1 / (1 + Math.exp(-x));
  }

  // Derivative of sigmoid
  sigmoidDerivative(y) {
    return y * (1 - y); // assuming y = sigmoid(x)
  }

  // Forward pass
  forward(inputs) {
    // Hidden layer
    const hidden = this.weightsInputHidden.map((weights, i) => {
      const sum = weights.reduce((acc, weight, j) => acc + weight * inputs[j], 0) + this.biasHidden[i];
      return this.sigmoid(sum);
    });

    // Output layer
    const outputs = this.weightsHiddenOutput.map((weights, i) => {
      const sum = weights.reduce((acc, weight, j) => acc + weight * hidden[j], 0) + this.biasOutput[i];
      return this.sigmoid(sum);
    });

    return { hidden, outputs };
  }

  // Train on one example
  train(inputs, targets) {
    const { hidden, outputs } = this.forward(inputs);

    // Output errors
    const outputErrors = targets.map((target, i) => target - outputs[i]);

    // Output gradients
    const outputGradients = outputs.map((output, i) =>
      outputErrors[i] * this.sigmoidDerivative(output)
    );

    // Hidden -> Output weight updates
    for (let i = 0; i < this.outputSize; i++) {
      for (let j = 0; j < this.hiddenSize; j++) {
        this.weightsHiddenOutput[i][j] += this.learningRate * outputGradients[i] * hidden[j];
      }
      this.biasOutput[i] += this.learningRate * outputGradients[i];
    }

    // Hidden errors
    const hiddenErrors = Array(this.hiddenSize).fill(0);
    for (let i = 0; i < this.hiddenSize; i++) {
      for (let j = 0; j < this.outputSize; j++) {
        hiddenErrors[i] += this.weightsHiddenOutput[j][i] * outputGradients[j];
      }
    }

    // Hidden gradients
    const hiddenGradients = hidden.map((h, i) =>
      hiddenErrors[i] * this.sigmoidDerivative(h)
    );

    // Input -> Hidden weight updates
    for (let i = 0; i < this.hiddenSize; i++) {
      for (let j = 0; j < this.inputSize; j++) {
        this.weightsInputHidden[i][j] += this.learningRate * hiddenGradients[i] * inputs[j];
      }
      this.biasHidden[i] += this.learningRate * hiddenGradients[i];
    }
  }

  // Predict output
  predict(inputs) {
    return this.forward(inputs).outputs;
  }
}
```

