## 2. `server.js`

This backend serves the website and handles the API request.

```js
const express = require("express");
const path = require("path");
require("dotenv").config();

const app = express();
const PORT = process.env.PORT || 3000;

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

app.post("/generate-image", async (req, res) => {
  try {
    const { prompt } = req.body;

    if (!prompt) {
      return res.status(400).json({ error: "Prompt is required" });
    }

    // Replace this URL with your Stable Diffusion API endpoint
    const apiUrl = "https://your-stable-diffusion-api.com/generate";

    // Example request body - adjust to your API's format
    const payload = {
      prompt: prompt,
      steps: 30,
      width: 512,
      height: 512
    };

    const response = await fetch(apiUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        // If your API requires auth:
        // "Authorization": `Bearer ${process.env.SD_API_KEY}`
      },
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
      const errorText = await response.text();
      return res.status(response.status).json({
        error: "Stable Diffusion API request failed",
        details: errorText
      });
    }

    const data = await response.json();

    // Adjust this depending on the API response shape
    // Common possibilities:
    // data.image
    // data.images[0]
    // data.output[0]
    const imageUrlOrBase64 = data.image || data.images?.[0] || data.output?.[0];

    if (!imageUrlOrBase64) {
      return res.status(500).json({
        error: "No image returned from API",
        rawResponse: data
      });
    }

    res.json({ image: imageUrlOrBase64 });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: "Server error while generating image" });
  }
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

