## 5. `public/app.js`

```js
const form = document.getElementById("prompt-form");
const promptInput = document.getElementById("prompt");
const statusDiv = document.getElementById("status");
const imageEl = document.getElementById("generated-image");

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const prompt = promptInput.value.trim();

  if (!prompt) {
    statusDiv.textContent = "Please enter a prompt.";
    return;
  }

  statusDiv.textContent = "Generating image...";
  imageEl.style.display = "none";
  imageEl.src = "";

  try {
    const response = await fetch("/generate-image", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ prompt })
    });

    const data = await response.json();

    if (!response.ok) {
      statusDiv.textContent = data.error || "Something went wrong.";
      console.error(data);
      return;
    }

    // Handle either a direct URL or base64 image string
    let imageSrc = data.image;

    if (
      imageSrc &&
      !imageSrc.startsWith("http") &&
      !imageSrc.startsWith("data:image")
    ) {
      imageSrc = `data:image/png;base64,${imageSrc}`;
    }

    imageEl.src = imageSrc;
    imageEl.style.display = "block";
    statusDiv.textContent = "Image generated successfully!";
  } catch (error) {
    console.error(error);
    statusDiv.textContent = "Failed to generate image.";
  }
});
```

