```java
public class GrayCode {

    public enum Direction {
        FORWARD,
        BACKWARD
    }

    /**
     * Returns the next Gray code in the given direction.
     *
     * @param grayCode current Gray code value
     * @param bits number of bits in the sequence
     * @param direction rotation direction
     * @return next Gray code value
     */
    public static int nextGrayCode(int grayCode, int bits, Direction direction) {
        int max = 1 << bits;

        // Convert Gray code to binary index
        int binary = grayToBinary(grayCode);

        // Move forward or backward in the cyclic sequence
        if (direction == Direction.FORWARD) {
            binary = (binary + 1) % max;
        } else {
            binary = (binary - 1 + max) % max;
        }

        // Convert back to Gray code
        return binaryToGray(binary);
    }

    /**
     * Converts binary number to Gray code.
     */
    public static int binaryToGray(int binary) {
        return binary ^ (binary >> 1);
    }

    /**
     * Converts Gray code to binary number.
     */
    public static int grayToBinary(int gray) {
        int binary = gray;
        while ((gray >>= 1) != 0) {
            binary ^= gray;
        }
        return binary;
    }

    public static void main(String[] args) {
        int bits = 3;
        int currentGray = 0b011; // example Gray code
        int next = nextGrayCode(currentGray, bits, Direction.FORWARD);
        int prev = nextGrayCode(currentGray, bits, Direction.BACKWARD);

        System.out.println("Current: " + Integer.toBinaryString(currentGray));
        System.out.println("Next:    " + Integer.toBinaryString(next));
        System.out.println("Prev:    " + Integer.toBinaryString(prev));
    }
}
