      const formData = new FormData();
      formData.append("file", result, result.name || file.name);

      // upload formData
    },
    error(err) {
      console.error(err.message);
    },
  });
};
```

### Important note
You should also validate the MIME type on the backend. Frontend checks can be bypassed.

### Optional improvement
Some browsers may report uncommon MIME values or users may rename files. If you want, you can also check the file extension as a secondary check:

```js
const ALLOWED_EXTENSIONS = [".jpg", ".jpeg", ".png", ".svg", ".gif", ".webp"];

const hasAllowedExtension = (filename) =>
  ALLOWED_EXTENSIONS.some((ext) =>
    filename.toLowerCase().endsWith(ext)
  );
```

Then validate both:

```js
if (!ALLOWED_TYPES.includes(file.type) || !hasAllowedExtension(file.name)) {
  alert("Invalid file type.");
  e.target.value = "";
  return;
}
```

